                             (LAPACKE_lsame( jobu, 's' ) ? MIN(m,n) : 1);
        lapack_int nrows_v = LAPACKE_lsame( jobv, 'a' ) ? n :
                              ( LAPACKE_lsame( jobv, 's' ) ? MIN(m,n) : 1);
        lapack_int lda_t = MAX(1,m);
        lapack_int ldu_t = MAX(1,nrows_u);
