        lapack_int lda_t = MAX(1,m);
        lapack_int ldb_t = MAX(1,p);
        lapack_int ldq_t = MAX(1,n);
        lapack_int ldu_t = MAX(1,m);
        lapack_int ldv_t = MAX(1,p);
        float* a_t = NULL;
        float* b_t = NULL;
        float* u_t = NULL;
        float* v_t = NULL;
        float* q_t = NULL;
