                             ( LAPACKE_lsame( storev, 'r' ) ? k : 1);
        ncols_v = LAPACKE_lsame( storev, 'c' ) ? k :
                             ( LAPACKE_lsame( storev, 'r' ) ? n : 1);
        ldt_t = MAX(1,k);
        ldv_t = MAX(1,nrows_v);
        /* Check leading dimension(s) */
        if( ldt < k ) {
            info = -10;
            LAPACKE_xerbla( "LAPACKE_slarft_work", info );
            return info;
        }
