        if( ldbb < n ) {
            info = -10;
            LAPACKE_xerbla( "LAPACKE_ssbgvd_work", info );
            return info;
        }
        if( ldz < n ) {
            info = -13;
            LAPACKE_xerbla( "LAPACKE_ssbgvd_work", info );
            return info;
        }
